async function parseExcel(file:File){setBusy(true);try{const ExcelJS=await import('exceljs');const book=new ExcelJS.Workbook();await book.xlsx.load(await file.arrayBuffer());const sheet=book.worksheets.find(w=>w.state==='visible')||book.worksheets[0];if(!sheet)throw Error('No hay hojas');const normal=(x:any)=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');const heads:Item={};sheet.getRow(1).eachCell((c,col)=>heads[normal(c.text)]=col);const cols:Item={fleet:heads.flota||heads.numeroflota,license:heads.licencia||heads.numerolicencia,plate:heads.matricula,model:heads.modelo||heads.modelovehiculo,name:heads.nombreflota||heads.titular||heads.asociado,driver:heads.nombreconductor||heads.conductor||heads.nombre,phone:heads.telefono,phone2:heads.telefono2,requirements:heads.requerimientos||heads.compatibilidades,shift:heads.turno,driverNumber:heads.nconductor};if(!cols.fleet||!cols.name)throw Error(t('Se necesitan las columnas Flota y Nombre Flota (o Titular).','Calen les columnes Flota i Nombre Flota (o Titular).'));const map=new Map<string,Item>();sheet.eachRow((row,n)=>{if(n===1)return;const get=(k:string)=>cols[k]?row.getCell(cols[k]).text.trim():'';const fleet=get('fleet');if(!fleet)return;if(!get('name'))throw Error('Fila '+n+': falta el titular');const values={fleet,license:get('license'),name:get('name'),plate:get('plate'),model:get('model'),requirements:get('requirements').split(/[,;|]/).map(x=>x.trim()).filter(Boolean)};let m=map.get(fleet);if(m){for(const k of ['name','license','plate','model'])if(m[k]!==values[k as keyof typeof values])throw Error('Datos contradictorios en flota '+fleet)}else{m={...values,drivers:[]};map.set(fleet,m)}if(get('driver')){const d={id:fleet+'-'+(get('driverNumber')||normal(get('driver'))),name:get('driver'),phone:get('phone'),phone2:get('phone2'),shift:get('shift')};if(m.drivers.some((x:Item)=>x.id===d.id))throw Error('Conductor duplicado en flota '+fleet);m.drivers.push(d)}});if(!map.size)throw Error('No se han encontrado asociados');setImports([...map.values()]);setImportChoices({});go('users');toast.success(t('Archivo leído. Revisa el resumen antes de aplicar.','Fitxer llegit. Revisa el resum abans d’aplicar.'))}catch(e){toast.error((e as Error).message)}finally{setBusy(false);if(importRef.current)importRef.current.value=''}}
