{section==='schedule'&&<><div className="page-heading"><div><p className="eyebrow">{t('COORDINACIÓN DE DELEGADOS','COORDINACIÓ DE DELEGATS')}</p><h1>{t('Cuadrante semanal','Quadrant setmanal')}</h1><p>{t('Cobertura 24 h · Mínimo un delegado · Hora de Barcelona','Cobertura 24 h · Mínim un delegat · Hora de Barcelona')}</p></div><button className="primary" onClick={()=>open('shift.create',{userId:user.id,start:week+'T08:00',end:week+'T16:00'})}><Plus size={18}/>{t('Apuntarme a un turno','Apunta’m a un torn')}</button></div><div className="toolbar"><div className="week-picker"><button aria-label="Semana anterior" onClick={()=>setWeek(dateAdd(week,-7))}><ChevronLeft size={20}/></button><strong>{fmt(week+'T12:00:00')} — {fmt(dateAdd(week,6)+'T12:00:00')}</strong><button aria-label="Semana siguiente" onClick={()=>setWeek(dateAdd(week,7))}><ChevronRight size={20}/></button></div><button className="secondary" onClick={()=>setWeek(monday())}>{t('Esta semana','Aquesta setmana')}</button><span className="coverage-pill">{Math.round(cov.minutes/100.8)}% {t('cubierto','cobert')}</span>{admin&&<button className="secondary" disabled={busy||!cov.gaps.length} onClick={()=>act({type:'coverage.send',week})}><Bell size={16}/>{t('Avisar de huecos','Avisa dels buits')}</button>}</div><div className="week-grid">{Array.from({length:7},(_,i)=>{const day=dateAdd(week,i);const shifts=s.shifts.filter(sh=>sh.status!=='cancelled'&&sh.start<dateAdd(day,1)+'T00:00'&&sh.end>day+'T00:00').sort((a,b)=>a.start.localeCompare(b.start));const gap=cov.gaps.reduce((sum,[a,b])=>sum+Math.max(0,Math.min(b,(i+1)*1440)-Math.max(a,i*1440)),0);return <section className="day-column" key={day}><header><span>{new Date(day+'T12:00:00').toLocaleDateString(lang==='ca'?'ca-ES':'es-ES',{weekday:'short'})}</span><strong>{Number(day.slice(-2))}</strong></header><div className="day-shifts">{shifts.map(sh=><button key={sh.id} className={'shift '+(sh.userId===user.id?'mine':'')} onClick={()=>open('shift.detail',sh)}><strong>{sh.start.slice(0,10)<day?'00:00':time(sh.start)} — {sh.end.slice(0,10)>day?'24:00':time(sh.end)}</strong><span>{person(sh.userId)}</span>{sh.status==='cancel_requested'&&<small>{t('Cancelación pendiente','Cancel·lació pendent')}</small>}</button>)}{gap>0&&<div className="gap"><Clock3 size={16}/><strong>{(gap/60).toFixed(gap%60?1:0)} h</strong><span>{t('sin cubrir','sense cobrir')}</span><small>{cov.gaps.filter(([a,b])=>b>i*1440&&a<(i+1)*1440).map(([a,b])=>{const f=(v:number)=>String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0');return f(Math.max(a,i*1440)-i*1440)+'–'+f(Math.min(b,(i+1)*1440)-i*1440)}).join(' · ')}</small></div>}<button className="add-shift" onClick={()=>open('shift.create',{userId:user.id,start:day+'T08:00',end:day+'T16:00'})}><Plus size={17}/>{t('Apuntarme','Apunta’m')}</button></div></section>})}</div><div className="info-line"><AlertCircle size={17}/>{t('Los avisos automáticos del viernes y las notificaciones con la app cerrada están pendientes de activar. En esta prueba, administración puede enviar el aviso manualmente.','Els avisos automàtics de divendres i les notificacions amb l’app tancada estan pendents d’activar. En aquesta prova, administració pot enviar l’avís manualment.')}</div>{s.coverageRequests.filter(r=>r.week===week).slice(0,1).map(r=><section className="panel padded" key={r.id}><h2>{t('Solicitud de cobertura','Sol·licitud de cobertura')}</h2><p>{t('Indica a administración si puedes cubrir alguno de los huecos.','Indica a administració si pots cobrir algun dels buits.')}</p><button className="secondary" onClick={()=>open('coverage.reply',{id:r.id,text:r.responses.find((x:Item)=>x.userId===user.id)?.text||''})}>{t('Responder a administración','Respon a administració')}</button>{admin&&r.responses.map((x:Item)=><p key={x.userId}><strong>{x.name}:</strong> {x.text}</p>)}</section>)}</>}
{section==='chat'&&<><div className="page-heading"><div><p className="eyebrow">{t('EN CONTACTO','EN CONTACTE')}</p><h1>{t('Chat interno','Xat intern')}</h1><p>{t('Conversaciones para coordinar el día a día.','Converses per coordinar el dia a dia.')}</p></div></div><div className="chat-layout panel"><aside className="channels"><button className={channel==='general'?'selected':''} onClick={()=>setChannel('general')}><span className="channel-icon"><Users size={20}/></span><span><strong>{t('Equipo de delegados','Equip de delegats')}</strong><small>{t('Grupo general','Grup general')}</small></span></button>{!admin?<button className={channel===user.id?'selected':''} onClick={()=>setChannel(user.id)}><ShieldCheck/><span><strong>{t('Administración','Administració')}</strong><small>{t('Conversación privada','Conversa privada')}</small></span></button>:<><div className="nav-caption">{t('BUZÓN DE ADMINISTRACIÓN','BÚSTIA D’ADMINISTRACIÓ')}</div>{s.users.filter(u=>u.role==='delegate'&&u.status==='active').map(u=><button key={u.id} className={channel===u.id?'selected':''} onClick={()=>setChannel(u.id)}><span className="avatar">{initials(u.name)}</span><span><strong>{u.name}</strong><small>{t('Privado con administración','Privat amb administració')}</small></span></button>)}</>}</aside><section className="chat-main"><header><strong>{channel==='general'?t('Equipo de delegados','Equip de delegats'):t('Buzón privado','Bústia privada')+' · '+person(channel)}</strong><small>{channel==='general'?t('Visible para todos los delegados','Visible per a tots els delegats'):t('Visible para el delegado y todos los administradores','Visible per al delegat i tots els administradors')}</small></header><div className="messages">{s.messages.filter(m=>m.channel===channel).map(m=><div key={m.id} className={'message '+(m.author===user.id?'own':'')}><strong>{m.authorName}</strong><p>{m.text}</p>{fileLinks(m.files)}<small>{fmt(m.created)} · {new Date(m.created).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Madrid'})}</small></div>)}{!s.messages.some(m=>m.channel===channel)&&<div className="empty"><MessagesSquare/><p>{t('Inicia esta conversación.','Inicia aquesta conversa.')}</p></div>}<div ref={endRef}/></div><div className="composer">{recordError&&<p className="error">{recordError}</p>}{attachments.map(f=><span key={f.id} className="tag blue">{f.name}<button onClick={()=>setAttachments(a=>a.filter(x=>x.id!==f.id))}>×</button></span>)}<form onSubmit={async e=>{e.preventDefault();if(await act({type:'chat.send',channel,text:chatText,files:attachments}))setChatText('')}}><button type="button" title={t('Adjuntar','Adjunta')} onClick={()=>fileRef.current?.click()}><Paperclip size={21}/></button><input placeholder={t('Escribe un mensaje…','Escriu un missatge…')} value={chatText} onChange={e=>setChatText(e.target.value)}/><button type="button" className={recording?'recording':''} onClick={record} title={t('Nota de voz','Nota de veu')}>{recording?<Square size={20}/>:<Mic size={21}/>}</button><button className="send" disabled={busy||recording||(!chatText.trim()&&!attachments.length)} aria-label="Enviar"><Send size={19}/></button></form>{recording&&<small className="urgent-text">{t('Grabando… Pulsa el cuadrado para terminar.','Gravant… Prem el quadrat per acabar.')}</small>}</div></section></div></>}
