{section==='polls'&&<><div className="page-heading"><div><p className="eyebrow">{t('PARTICIPACIÓN','PARTICIPACIÓ')}</p><h1>{t('Encuestas','Enquestes')}</h1><p>{t('Tu opinión también forma parte del equipo.','La teva opinió també forma part de l’equip.')}</p></div>{admin&&<button className="primary" onClick={()=>open('poll.create',{anonymous:true,optionsText:'',closes:dateAdd(monday(),14)+'T18:00'})}><Plus size={18}/>{t('Crear encuesta','Crea una enquesta')}</button>}</div><div className="poll-grid">{s.polls.map(p=><section key={p.id} className="panel padded poll"><div className="flex-between"><span className={'tag '+(Date.parse(p.closes)>Date.now()?'resolved':'neutral')}>{Date.parse(p.closes)>Date.now()?t('Abierta','Oberta'):t('Cerrada','Tancada')}</span><small>{p.anonymous?t('Voto anónimo','Vot anònim'):t('Voto identificado','Vot identificat')}</small></div><h2>{p.title}</h2><p>{t('Cierre','Tancament')}: {fmt(p.closes)} · {time(p.closes)}</p>{p.options.map((o:string,i:number)=>{const total=p.counts.reduce((a:number,b:number)=>a+b,0),pct=total?Math.round(p.counts[i]/total*100):0;return <button key={i} disabled={busy||Date.parse(p.closes)<Date.now()} className={'poll-option '+(p.myVote===i?'chosen':'')} onClick={()=>act({type:'poll.vote',id:p.id,option:i})}><span className="poll-fill" style={{width:pct+'%'}}/><span>{p.myVote===i&&<Check size={17}/>} {o}</span><strong>{pct}%</strong></button>})}<small>{p.counts.reduce((a:number,b:number)=>a+b,0)} {t('votos','vots')} · {p.myVote!==undefined?t('Tu voto está guardado','El teu vot està desat'):t('Selecciona una opción para votar','Selecciona una opció per votar')}</small>{!p.anonymous&&p.votes.length>0&&<div className="vote-list">{p.votes.map((v:Item)=><p key={v.userId}>{person(v.userId)}: {p.options[v.option]}</p>)}</div>}</section>)}</div></>}
